-- 0042 Short motion scores: how much the FIRST FEW FRAMES of each 9:16
-- Short move (mean inter-frame abs difference of the first ~2 s, 0-255 scale).
-- The feed's "Short clips" carousel autoplays each card muted + looping while
-- on screen, so clips that open on a static title card look dead: the feed
-- orders clips by motion DESC (see worker/routes/shorts.ts `orderMotion`).
--
-- Scored by scripts/short_motion.py:
--   * backfill: every live Short's served file (showcase file if the record
--     has one, else the clips-v/ twin) — the INSERTs below;
--   * ongoing: crawler/ingest/clips.py scores each rendered twin at render
--     time; scripts/publish.sh --showcase scores the hand-made file at upload.
-- Re-run the backfill any time cuts are re-rendered (INSERT ... ON CONFLICT
-- DO UPDATE is idempotent).
CREATE TABLE IF NOT EXISTS short_motion (
  record_id TEXT NOT NULL,
  kind TEXT NOT NULL CHECK (kind IN ('showcase', 'twin')),
  motion REAL NOT NULL,
  frames INTEGER NOT NULL DEFAULT 0,
  computed_at INTEGER NOT NULL,
  PRIMARY KEY (record_id, kind)
);
CREATE INDEX IF NOT EXISTS idx_short_motion_motion ON short_motion (motion DESC);

